-- Read-only dossier per sampled lot, run 74. Flags: those open at run 74.
select json_build_object(
 'id', l.id, 'tlid', l.tlid, 'county', l.county, 'jurisdiction', l.jurisdiction, 'zone_raw', l.zone_raw, 'zone', l.zone,
 'address', l.site_address, 'area_sqft', l.area_sqft, 'facts', l.facts, 'srid', ST_SRID(l.geom),
 'geom', ST_AsGeoJSON(l.geom)::json,
 'results', (select json_agg(json_build_object('design', r.design_key, 'tier', r.tier, 'slack_ft', r.slack_ft, 'binding', r.binding, 'checks', r.checks) order by r.design_key) from flats.lot_results r where r.lot_id=l.id and r.run_id=74),
 'flags', (select json_agg(json_build_object('design', f.design_key, 'code', f.code, 'sev', f.severity, 'colour', f.colour, 'status', f.status, 'source', f.source, 'low', f.bounds_low, 'high', f.bounds_high)) from flats.flag_instances f where f.tlid=l.tlid and f.county=l.county and coalesce(f.opened_run_id,0) <= 74 and (f.cleared_run_id is null or f.cleared_run_id > 74)),
 'neighbours', (select json_agg(json_build_object('tlid', n.tlid, 'zone', n.zone, 'area', n.area_sqft, 'addr', n.site_address, 'geom', ST_AsGeoJSON(n.geom)::json)) from flats.lots n where n.snapshot_id=l.snapshot_id and n.id<>l.id and ST_DWithin(n.geom, l.geom, 120))
)
from flats.lots l where l.id in (21666288,21666466,21665692,21665367,21557870,21561966,21570296,21570469,21114201,21115551,21566957,21633524,21633430,21620247,21629155,21523962,21531124,21550355,21116470,21116337,21549578,21565298,21533146,21647384,21648457,21496260,21479776,21279277,21454970,21483712,21428855,21353605,21454035,21369285,21242161,21375639,21454322,21446243,21185128,21258060,21239671,21179405,21432056,21390489,21243539,21381260,21371874,21441183,21443173,21375901,21178864,21242948,21445711,21158475,21368983,21252752,21456029,21178468,21283454,21283511,21466197,21500187,21282351,21282320,21146178,21330474,21146948,21311161,21271877,21472832,21271875,21473001,21270624,21271394,21612609,21612611,21221588,21401729,21272800,21221905,21221893,21401628,21615111,21626948,21625873,21610933,21609194,21595530,21596099,21341139,21593995,21340682,21596159,21314091,21294528,21325988,21392660,21408676,21604439,21327422,21214541,21324420,21306029,21143030,21392662,21313723,21306594,21134315);
